package org.rabochaya.maptests;
import android.app.*;import android.content.*;import android.accessibilityservice.AccessibilityServiceInfo;import android.view.*;import android.widget.*;import java.util.*;import org.json.*;
/** Probe only: raw vertex form and its owning unsaved geometry must survive real recreation. */
final class VertexRotationChecks {
 final MapAndroidChecks m;final ManagerVisualChecks v;final ManagerRotationChecks r;final ManagerMoveChecks fixture;
 final String mainText="20.5 10.5 30.5";
 VertexRotationChecks(MapAndroidChecks m){this.m=m;v=new ManagerVisualChecks(m);r=new ManagerRotationChecks(m);fixture=new ManagerMoveChecks(m);}
 EditText field(View root){if(root instanceof EditText&&"Координаты вершины WGS 84".contentEquals(root.getContentDescription()==null?"":root.getContentDescription()))return (EditText)root;if(root instanceof ViewGroup){ViewGroup g=(ViewGroup)root;for(int i=0;i<g.getChildCount();i++){EditText found=field(g.getChildAt(i));if(found!=null)return found;}}return null;}
 JSONObject state()throws Exception{final JSONObject out=new JSONObject();final RuntimeException[] error={null};m.runOnMainSync(()->{try{EditText f=field(m.activeDialogRoot());out.put("present",f!=null);out.put("text",f==null?"":f.getText().toString());out.put("start",f==null?-1:f.getSelectionStart());out.put("end",f==null?-1:f.getSelectionEnd());out.put("error",f==null||f.getError()==null?"":f.getError().toString());}catch(Exception e){error[0]=new RuntimeException(e);}});if(error[0]!=null)throw error[0];return out;}
 void snapshot(String name)throws Exception{JSONObject o=state();o.put("name",name);o.put("orientation",m.activity.getResources().getConfiguration().orientation);o.put("mainText",m.geometryInput());o.put("imeWindows",v.imeWindows());final JSONArray texts=new JSONArray();final RuntimeException[] error={null};m.runOnMainSync(()->{try{v.inspect(m.activeDialogRoot(),texts);}catch(Exception e){error[0]=new RuntimeException(e);}});if(error[0]!=null)throw error[0];o.put("texts",texts);m.capture("mvisual-"+name);v.emit("VERTEX_VISUAL "+o.toString());}
 void rotate(int rotation)throws Exception{final int desired=rotation==UiAutomation.ROTATION_FREEZE_0?1:2;m.check(m.getUiAutomation().setRotation(rotation),"vertex rotation requested");long end=System.currentTimeMillis()+15000;int stable=0;final int[] data=new int[3];while(System.currentTimeMillis()<end){m.runOnMainSync(()->{View root=m.activeDialogRoot();ViewGroup content=(ViewGroup)root.findViewById(android.R.id.content);if(content!=null&&content.getChildCount()>0){Context c=content.getChildAt(0).getContext();while(c instanceof ContextWrapper&&!(c instanceof Activity))c=((ContextWrapper)c).getBaseContext();if(c instanceof Activity&&c.getClass().getName().equals("org.rabochaya.projects.GeometryEditorActivity"))m.activity=(Activity)c;}View decor=m.activity.getWindow().getDecorView();data[0]=decor.getWidth();data[1]=decor.getHeight();data[2]=m.activity.getResources().getConfiguration().orientation;});boolean dimensions=desired==1?data[1]>data[0]:data[0]>data[1];if(!m.activity.isDestroyed()&&data[2]==desired&&dimensions){if(++stable>=3){m.geometryReady();return;}}else stable=0;Thread.sleep(100);}throw new AssertionError("vertex orientation did not settle "+Arrays.toString(data));}
 boolean scenario(Object store,String kind)throws Exception{long id=fixture.insert(store);try{Object doc=r.load(store,id);byte[] xml=r.xml(doc);Map<String,byte[]> assets=new HashMap<>(m.assets(doc));v.finish();m.getUiAutomation().setRotation(UiAutomation.ROTATION_FREEZE_0);m.activity=m.startActivitySync(new Intent().setClassName(m.getTargetContext().getPackageName(),"org.rabochaya.projects.GeometryEditorActivity").putExtra("project",id).putExtra("feature","point").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));rotate(UiAutomation.ROTATION_FREEZE_0);m.check(m.activity.getResources().getConfiguration().orientation==1,"vertex starts in settled portrait");m.inputs(mainText);m.click("Действия");m.click("Редактировать вершины");m.click("1. 20.5 10.5 30.5");m.click("Изменить координаты");String raw=kind.equals("invalid")?"91 0":"21.25 31.75 41.5";m.inputs(raw);v.keyboard();if(kind.equals("invalid"))m.click("Применить");m.runOnMainSync(()->{EditText f=field(m.activeDialogRoot());if(f==null)throw new AssertionError("raw vertex field before rotation");f.setSelection(1,3);});JSONObject before=state();m.check(before.getBoolean("present")&&before.getString("text").equals(raw)&&before.getInt("start")==1&&before.getInt("end")==3,"exact raw vertex/cursor fixture");m.check(!before.getString("error").isEmpty()==kind.equals("invalid"),"vertex validation state fixture");snapshot("vertex-"+kind+"-before");JSONObject stable=state();m.check(stable.getBoolean("present")&&stable.getString("text").equals(before.getString("text"))&&stable.getInt("start")==1&&stable.getInt("end")==3&&stable.getString("error").equals(before.getString("error")),"raw vertex fixture remains exact immediately before actual rotation");Activity old=m.activity;rotate(UiAutomation.ROTATION_FREEZE_90);m.check(old!=m.activity&&old.isDestroyed(),"vertex Activity really destroyed and replaced");snapshot("vertex-"+kind+"-after");JSONObject after=state();boolean restored=after.getBoolean("present")&&after.getString("text").equals(raw)&&after.getInt("start")==1&&after.getInt("end")==3&&after.getString("error").equals(before.getString("error"));m.check(m.geometryInput().equals(mainText),"owning unsaved main geometry remains exact");m.check(Arrays.equals(xml,r.xml(r.load(store,id))),"vertex probe/recreation never writes KML");r.sameAssets(r.load(store,id),assets);v.emit("VERTEX_BASELINE kind="+kind+" restored="+restored+" main/KML/assets unchanged=true");return restored;}finally{v.finish();m.call(store,"remove",new Class[]{long.class},id);}}
 void run()throws Exception{m.installTileFixture();int requests=m.requests.get();Object store=m.storeClass.getConstructor(Context.class).newInstance(m.getTargetContext());AccessibilityServiceInfo service=m.getUiAutomation().getServiceInfo();int flags=service.flags;service.flags|=AccessibilityServiceInfo.FLAG_RETRIEVE_INTERACTIVE_WINDOWS;m.getUiAutomation().setServiceInfo(service);String keyboard=v.shell("settings get secure show_ime_with_hard_keyboard").trim();boolean all=true;try{v.shell("settings put secure show_ime_with_hard_keyboard 1");for(String kind:new String[]{"valid","invalid"})all&=scenario(store,kind);m.check(m.requests.get()==requests,"raw vertex form makes no tile requests");m.check(all,"raw vertex form, cursor and error survive actual Activity recreation");}finally{v.finish();service.flags=flags;m.getUiAutomation().setServiceInfo(service);m.getUiAutomation().setRotation(UiAutomation.ROTATION_UNFREEZE);v.shell(keyboard.equals("null")?"settings delete secure show_ime_with_hard_keyboard":"settings put secure show_ime_with_hard_keyboard "+keyboard);m.call(store,"close",new Class[]{});}}
}
